TAB_BossLevel[1] = {{0,99},{{56001,5}},5,{425091,60},{100011,100021,100031,100041},"Kim dài và kim ngắn của Tokisaki Kurumi lần lượt là súng trường và súng lục, dùng năng lượng Tokisaki Kurumi làm đạn bắn ra, con số trên đồng hồ có nhiều năng lực lớn mạnh khác nhau. Nhưng khi sử dụng thiên sứ cùng lúc sẽ tốn nhiều thời gian (Tuổi thọ như nhau), mắt trái Kurumi là đồng hồ vàng xoay tròn khi kích hoạt năng lực. Khi sức mạnh Tokisaki Kurumi kích hoạt, con số trên đồng hồ sẽ có một cái bóng đi vào đầu súng, sau đó đánh trúng mục tiêu mới tạo ra hiệu quả, chưa đánh trúng mục tiêu sẽ vô nghĩa.",30101,30010,{{1,1,30113},{2,2,30112},{3,3,30111},{4,10,30110},{11,15,30109},{16,20,30108},{21,50,30107},{51,100,30106},{101,200,30105},{201,500,30104},{501,1000,30103},{1001,99999,30102}},6002}
